let raw = msg.payload.toString();
let ZERO_OFFSET = 5.6;

let match = raw.match(/-?\d+(\.\d+)?/);
if (!match) return null;

let weight = parseFloat(match[0]);

let minChange = 0.10;
let stableDelay = 1500;

let lastWeight = context.get("lastWeight");
let lastTime = context.get("lastTime") || 0;
let now = Date.now();

if (lastWeight !== undefined) {
    let diff = Math.abs(weight - lastWeight);

    if (diff < minChange) return null;
    if (now - lastTime < stableDelay) return null;
}

context.set("lastWeight", weight);
context.set("lastTime", now);

msg.payload = weight-ZERO_OFFSET;
return msg;

let weight = Number(msg.payload);
if (isNaN(weight)) return null;

msg.payload = {
    date: new Date().toLocaleDateString(),
    time: new Date().toLocaleTimeString(),
    weight: weight,
    dailyTotal: flow.get("dailyTotal") || 0,
    bagCount: flow.get("bagCount") || 0,
    event: "weight_update"
};

return msg;

let weight = Number(msg.payload);
if (!Number.isFinite(weight)) return null;

// Prevent tiny negative readings around zero
weight = Math.max(0, weight);

// ======================================================
// SETTINGS
// ======================================================

// Ignore tiny fluctuations in the scale reading
const NOISE_TOLERANCE = 0.3; // 0.3

// A decrease must be at least this large before we even
// consider that someone may be removing the bag.
const REMOVAL_DROP = 1;  // 3.0

// During a possible bag change, readings this close
// together are considered stable.
const STABLE_TOLERANCE = 0.5;  // 0.5

// How many consecutive stable readings are required
// before confirming that the new bag is in place.
const STABLE_READINGS_NEEDED = 1;  // 4


// ======================================================
// STORED STATE
// ======================================================

let lastWeight = flow.get("lastWeight");
let savedTotal = flow.get("savedTotal") || 0;

let changingBag = flow.get("changingBag") || false;
let oldBagWeight = flow.get("oldBagWeight") || 0;

let stableCount = flow.get("stableCount") || 0;
let previousChangeWeight = flow.get("previousChangeWeight");


// ======================================================
// FIRST READING
// ======================================================

if (lastWeight === undefined || lastWeight === null) {

    flow.set("lastWeight", weight);

    msg.payload = Number(
        (savedTotal + weight).toFixed(2)
    );

    return msg;
}


// ======================================================
// NORMAL OPERATION
// ======================================================

if (!changingBag) {

    let difference = weight - lastWeight;


    // --------------------------------------------------
    // NORMAL INCREASE
    // Students are adding food.
    // --------------------------------------------------

    if (difference >= -NOISE_TOLERANCE) {

        flow.set("lastWeight", weight);

        msg.payload = Number(
            (savedTotal + weight).toFixed(2)
        );

        return msg;
    }


    // --------------------------------------------------
    // POSSIBLE BAG REMOVAL
    // --------------------------------------------------

    if (difference <= -REMOVAL_DROP) {

        changingBag = true;

        // Save the weight immediately before the drop.
        oldBagWeight = lastWeight;

        flow.set("changingBag", true);
        flow.set("oldBagWeight", oldBagWeight);

        flow.set("stableCount", 0);
        flow.set("previousChangeWeight", weight);

        // Freeze the displayed cumulative total while
        // somebody is physically changing the bag.
        msg.payload = Number(
            (savedTotal + oldBagWeight).toFixed(2)
        );

        return msg;
    }


    // --------------------------------------------------
    // SMALL/MEDIUM DECREASE
    // Probably vibration, someone touching the bin,
    // shifting food, etc. Do NOT call this a bag change.
    // --------------------------------------------------

    msg.payload = Number(
        (savedTotal + lastWeight).toFixed(2)
    );

    return msg;
}


// ======================================================
// POSSIBLE BAG CHANGE IN PROGRESS
// ======================================================

if (changingBag) {

    // If the weight shoots back near the old value,
    // the apparent removal was probably temporary.
    if (weight >= oldBagWeight - REMOVAL_DROP) {

        flow.set("changingBag", false);
        flow.set("stableCount", 0);
        flow.set("previousChangeWeight", undefined);
        flow.set("lastWeight", weight);

        msg.payload = Number(
            (savedTotal + weight).toFixed(2)
        );

        return msg;
    }


    // --------------------------------------------------
    // CHECK WHETHER NEW READING HAS STABILIZED
    // --------------------------------------------------

    if (
        previousChangeWeight !== undefined &&
        Math.abs(weight - previousChangeWeight) <= STABLE_TOLERANCE
    ) {

        stableCount++;

    } else {

        stableCount = 0;
    }

    flow.set("stableCount", stableCount);
    flow.set("previousChangeWeight", weight);


    // --------------------------------------------------
    // NEW BAG / EMPTY SCALE HAS STABILIZED
    // --------------------------------------------------

    if (stableCount >= STABLE_READINGS_NEEDED) {

        // Permanently save the completed bag.
        savedTotal += oldBagWeight;

        flow.set("savedTotal", savedTotal);

        // New reading is now the active bag/bin weight.
        flow.set("lastWeight", weight);

        // Exit bag-change mode.
        flow.set("changingBag", false);
        flow.set("oldBagWeight", 0);
        flow.set("stableCount", 0);
        flow.set("previousChangeWeight", undefined);

        // Increment bag count automatically.
        let bagCount = flow.get("bagCount") || 0;
        bagCount++;
        flow.set("bagCount", bagCount);

        msg.payload = Number(
            (savedTotal + weight).toFixed(2)
        );

        return msg;
    }


    // While the bag is being changed, keep the displayed
    // cumulative total frozen.
    msg.payload = Number(
        (savedTotal + oldBagWeight).toFixed(2)
    );

    return msg;
}

let bagCount = flow.get("bagCount") || 0;
bagCount += 1;

flow.set("bagCount", bagCount);
flow.set("lastAcceptedWeight", 0);

msg.payload = bagCount;
return msg;

let total = flow.get("dailyTotal") || 0;
let bags = flow.get("bagCount") || 0;

let report = {
    date: new Date().toLocaleDateString(),
    time: new Date().toLocaleTimeString(),
    dailyTotal: total.toFixed(2),
    bagCount: bags,
    event: "end_of_day"
};

// Reset old variables
flow.set("dailyTotal", 0);
flow.set("bagCount", 0);
flow.set("lastAcceptedWeight", 0);
flow.set("bagsChanged", 0);

// RESET VARIABLES USED BY NEW WEIGHT ALGORITHM
flow.set("savedTotal", 0);
flow.set("lastWeight", undefined);
flow.set("changingBag", false);
flow.set("oldBagWeight", 0);
flow.set("stableCount", 0);
flow.set("previousChangeWeight", undefined);

let reportMsg = {
    payload: report
};

let totalResetMsg = {
    payload: "0.00"
};

let bagResetMsg = {
    payload: 0
};

return [
    reportMsg,
    totalResetMsg,
    bagResetMsg
];

