let raw = msg.payload.toString();

// Split by commas
let parts = raw.split(",");

// Make sure the expected value exists
if (parts.length < 2) return null;

// Get weight (second value)
let weight = parseFloat(parts[1]);

// Ignore invalid readings
if (isNaN(weight)) return null;

// Output ONLY the weight
msg.payload = weight;

return msg;
